import {renderAuth} from '/auth.js';
const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state={profiles:[],posts:[],saved:[],liked:[],skipped:[],active:null};
async function api(path,body){const response=await fetch(path,{method:body?'POST':'GET',headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});const data=await response.json();if(!response.ok)throw new Error(data.error||'Verbindung fehlgeschlagen.');return data}
async function mutate(path,body){try{state=await api(path,body);render();return true}catch(e){toast(e.message);return false}}
function navigate(path){history.pushState({},'',path);render();window.scrollTo(0,0)}
window.addEventListener('popstate',()=>render());
function authForm(){navigate('/login')}
let page='Home',tab='Für dich',query='';
const svg=paths=>'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">'+paths+'</svg>';
const icons={Home:svg('<path d="m3 10 9-7 9 7v10H15v-7H9v7H3Z"/>'),Entdecken:svg('<circle cx="12" cy="12" r="9"/><path d="m16 8-2.5 5.5L8 16l2.5-5.5Z"/>'),Connections:svg('<path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8Z"/>'),Lesezeichen:svg('<path d="M6 3h12v18l-6-4-6 4Z"/>'),Profil:svg('<circle cx="12" cy="8" r="4"/><path d="M4 21v-2a8 8 0 0 1 16 0v2"/>')};
const me=()=>state.profiles.find(p=>p.id===state.active);
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function profileForm(){if(!me())return authForm();const p=me();$('#profileForm').reset();if(p){for(const k of ['name','role','bio','tags','link','twitch','youtube','social'])$('#profileForm').elements[k].value=p[k]||'';$('#profileForm').elements.collab.checked=p.collab}$('#profileDialog').showModal()}
function empty(symbol,title,text,button){return `<section class="empty"><div class="empty-symbol">${symbol}</div><h2>${title}</h2><p>${text}</p>${button||''}</section>`}
function posts(){let items=state.posts.filter(p=>page!=='Lesezeichen'||state.saved.includes(p.id)).filter(p=>tab!=='Connections'||state.liked.includes(p.author)||p.author===state.active).filter(p=>!query||p.text.toLowerCase().includes(query.toLowerCase()));return items.length?items.map(p=>{const a=state.profiles.find(a=>a.id===p.author);return `<article class="post"><div class="avatar">${esc(a?.name?.[0]||'V')}</div><div class="post-body"><div><strong>${esc(a?.name)}</strong> <span class="subtle">· ${new Date(p.date).toLocaleDateString('de-DE')}</span></div><p>${esc(p.text)}</p><div class="post-actions"><button data-like="${p.id}" class="${p.liked?'pink':''}" aria-label="Gefällt mir">${p.liked?'♥':'♡'} <span>${p.likes??0}</span></button><button data-save="${p.id}" aria-label="Lesezeichen">${state.saved.includes(p.id)?'▰ Gespeichert':'▱ Speichern'}</button><button data-share="${p.id}">↗ Teilen</button></div></div></article>`}).join(''):empty('✦',page==='Lesezeichen'?'Deine Favoriten finden hier Platz.':'Eine neue Community beginnt mit dir.',page==='Lesezeichen'?'Speichere Beiträge, die du später wiederfinden möchtest.':'Teile deinen ersten Gedanken, deinen nächsten Stream oder eine Idee für eine Collab.');}
function discover(){const candidates=state.profiles.filter(p=>p.id!==state.active&&p.role==='VTuber'&&(tab!=='Collabs'||p.collab)&&!state.skipped.includes(p.id)&&!state.liked.includes(p.id)&&(!query||(p.name+' '+p.tags).toLowerCase().includes(query.toLowerCase())));const p=candidates[0];return `<div class="section-intro"><span class="eyebrow">ENTDECKEN</span><h1>Finde VTuber für dich.</h1><p>Dein nächster Lieblingsstream. Oder deine nächste große Collab.</p></div><div class="discover-tabs"><button data-mode="Alle" class="${tab!=='Collabs'?'selected':''}">VTuber entdecken</button><button data-mode="Collabs" class="${tab==='Collabs'?'selected':''}">Collab-Partner</button></div>${p&&(tab!=='Collabs'||p.collab)?`<article class="swipe-card" tabindex="0"><div class="card-art ${esc(p.id.startsWith('demo-')?p.id:'')}"><span>${esc(p.name[0])}</span><div class="orbit o1"></div><div class="orbit o2"></div></div><div class="card-info"><span class="chip">${p.demo?'DEMO-PROFIL · ':''}${p.collab?'✧ Offen für Collabs':'VTuber'}</span><h2>${esc(p.name)}</h2><p>${esc(p.bio)}</p><div class="tags">${esc(p.tags)}</div></div></article><div class="swipe-actions"><button data-swipe="skip" data-id="${p.id}" aria-label="Überspringen">×</button><button data-swipe="like" data-id="${p.id}" aria-label="Merken">♡</button></div><p class="hint">Nach links überspringen · Nach rechts merken${!state.active?'<br><span>Ohne Anmeldung werden deine Swipes nicht gespeichert.</span>':''}</p>`:empty('✧','Du bist auf dem neuesten Stand.','Sobald weitere VTuber vorhanden sind, kannst du hier durch ihre Profile swipen.',`<button class="secondary" id="resetSwipes">Übersprungene erneut ansehen</button>`)}`}
function profile(p){return `<div class="profile-banner"><span>✦</span><i>YOUR NEXT CONNECTION STARTS HERE</i></div><section class="profile-content"><div class="profile-top"><div class="avatar big">${esc(p.name[0])}</div><div class="profile-options"><button class="secondary" id="editProfile">Profil bearbeiten</button><button class="logout mobile-logout" id="logoutProfile">Abmelden</button></div></div><h1>${esc(p.name)}</h1><span class="subtle">${esc(p.role)}</span><p>${esc(p.bio)}</p><div class="tags">${esc(p.tags)}</div>${p.collab?'<span class="chip">✧ Offen für Collabs</span>':''}${[['Website',p.link],['Twitch',p.twitch],['YouTube',p.youtube],['Social',p.social]].filter(([,url])=>url).map(([label,url])=>`<a class="link-card" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${label}<span>Öffnen ↗</span></a>`).join('')}</section>`}
function render(){if(['/login','/register'].includes(location.pathname)){renderAuth({register:location.pathname==='/register',api,navigate,onSuccess:data=>{state=data;navigate('/');toast('Du bist angemeldet.')}});return}document.title='VConnect · '+(page==='Home'?'Feed':page);const p=me();$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><a class="brand" href="#" aria-label="VConnect Home"><span class="brand-mark">v<span>✦</span></span>vconnect<span class="brand-period">.</span></a><nav>${Object.entries(icons).map(([label,icon])=>`<button data-page="${label}" class="${page===label?'active':''}"><span>${icon}</span>${label}</button>`).join('')}</nav><button class="primary post-button" id="write">Posten <span>＋</span></button><div class="sidebar-bottom"><button id="account" class="account"><span class="avatar">${esc(p?.name[0]||'＋')}</span><span><strong>${esc(p?.name||'Anmelden')}</strong><small>${p?'Profil bearbeiten':'Konto erstellen oder anmelden'}</small></span><b>···</b></button>${p?'<button id="logout" class="logout">Abmelden</button>':''}</div></aside><main><header><strong>${page==='Home'?'Dein Feed':page}</strong><div class="header-tools"><button data-page="Entdecken" aria-label="VTuber entdecken">${icons.Entdecken}</button>${!p?'<button class="header-login" id="headerLogin">Anmelden ↗</button>':''}</div></header>${page==='Home'?`<div class="feed-tabs"><button data-tab="Für dich" class="${tab==='Für dich'?'selected':''}">Für dich</button><button data-tab="Connections" class="${tab==='Connections'?'selected':''}">Connections</button></div><form id="compose" class="composer"><div class="avatar">${esc(p?.name[0]||'V')}</div><div><textarea id="postText" maxlength="500" aria-label="Beitrag" placeholder="Was passiert in deiner Welt?"></textarea><div class="compose-bottom"><span>✧ <small>Beitrag veröffentlichen</small></span><button class="primary" type="submit">Posten</button></div></div></form>${!p?`<section class="welcome"><span class="eyebrow">VTUBER ENTDECKEN. COLLABS FINDEN.</span><h1>Deine Welt.<br>Deine <em>Connections.</em></h1><p>Wo VTuber zusammenfinden und aus Zuschauern<br class="desktop"> eine Community wird.</p><button class="secondary" data-page="Entdecken">VTuber entdecken <span>↗</span></button><div class="welcome-art"><span>✧</span><b>✦</b><i>✧</i></div></section>`:''}<div class="section-label">Deine Timeline <span>✦</span></div>${posts()}`:page==='Entdecken'?discover():page==='Profil'?(p?profile(p):empty('◎','Erstelle dein Profil.','Ein Profil für deinen Vibe, deine Links und deine nächsten Connections.','<button class="primary" id="createProfile">Profil erstellen ↗</button>')):page==='Connections'?`<div class="section-intro"><span class="eyebrow">CONNECTIONS</span><h1>Deine Connections</h1><p>VTuber, die du dir beim Entdecken gemerkt hast.</p></div>${state.profiles.filter(p=>state.liked.includes(p.id)).map(p=>`<article class="connection"><div class="avatar">${esc(p.name[0])}</div><div><h2>${esc(p.name)} ${p.demo?'<small class="demo-badge">Demo</small>':''}</h2><p>${esc(p.bio)}</p>${p.link?`<a href="${esc(p.link)}" target="_blank" rel="noopener noreferrer">Stream besuchen ↗</a>`:''}</div></article>`).join('')||empty('♡','Noch keine Connections.','Entdecke VTuber und merke dir Profile, die zu dir passen.','<button class="primary" data-page="Entdecken">VTuber entdecken ↗</button>')}`:posts()}</main><aside class="rightbar"><label class="search"><span>⌕</span><input id="search" placeholder="VConnect durchsuchen" value="${esc(query)}" aria-label="VConnect durchsuchen"></label><section class="right-card discovery-promo"><span class="chip">✧ MADE FOR YOUR NEXT CHAPTER</span><h2>Wen entdeckst<br>du als Nächstes?</h2><p>Neue Stimmen. Gleicher Vibe.<br>Finde VTuber, die zu dir passen.</p><div class="mini-art">✧ <span>♡</span> ✦</div><button class="primary" data-page="Entdecken">Jetzt swipen <span>↗</span></button></section><section class="right-card"><h3>Dein nächster Schritt <span>↗</span></h3><button class="step" id="setup"><span>01</span><div><strong>Zeig, wer du bist</strong><small>Dein Profil ist deine Visitenkarte.</small></div></button><button class="step" data-page="Entdecken"><span>02</span><div><strong>Finde deinen Vibe</strong><small>Entdecke deine VTuber-Bubble.</small></div></button><button class="step" id="collabSetup"><span>03</span><div><strong>Zusammen ist mehr drin</strong><small>Öffne dein Profil für Collabs.</small></div></button></section><footer>VConnect © ${new Date().getFullYear()}<br><span>Mit ♥ für die VTuber-Community</span></footer></aside></div>`;bind()}
function bind(){
 if($('#headerLogin'))$('#headerLogin').onclick=authForm;
 document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{page=b.dataset.page;tab='Für dich';query='';render();window.scrollTo(0,0)});
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;render()});
 document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{tab=b.dataset.mode;render()});
 for(const id of ['account','setup','collabSetup','editProfile','createProfile'])if($('#'+id))$('#'+id).onclick=profileForm;
 for(const id of ['logout','logoutProfile'])if($('#'+id))$('#'+id).onclick=async()=>{if(await mutate('/api/logout',{})){page='Home';navigate('/login')}};
 $('#write').onclick=()=>{if(!me())return authForm();page='Home';render();$('#postText').focus()};
 if($('#compose'))$('#compose').onsubmit=async e=>{e.preventDefault();if(!me())return authForm();const text=$('#postText').value.trim();if(text)await mutate('/api/posts',{text})};
 document.querySelectorAll('[data-like]').forEach(b=>b.onclick=()=>{if(!me())return authForm();const p=state.posts.find(p=>p.id===b.dataset.like);mutate('/api/interactions',{target:p.id,kind:'post-like',enabled:!p.liked})});
 document.querySelectorAll('[data-save]').forEach(b=>b.onclick=()=>{if(!me())return authForm();mutate('/api/interactions',{target:b.dataset.save,kind:'save',enabled:!state.saved.includes(b.dataset.save)})});
 document.querySelectorAll('[data-share]').forEach(b=>b.onclick=async()=>{try{await navigator.clipboard.writeText(state.posts.find(p=>p.id===b.dataset.share).text);toast('Beitrag kopiert')}catch{toast('Kopieren nicht verfügbar.')}});
 $('#search').onchange=e=>{query=e.target.value;if(!['Entdecken','Home','Lesezeichen'].includes(page))page='Entdecken';render()};
 document.querySelectorAll('[data-swipe]').forEach(b=>b.onclick=()=>swipe(b.dataset.id,b.dataset.swipe));
 if($('#resetSwipes'))$('#resetSwipes').onclick=async()=>{if(me())await mutate('/api/reset-swipes',{});else{state.skipped=[];state.liked=[];render()}};
 const card=$('.swipe-card');if(card){let start;card.onpointerdown=e=>{start=e.clientX};card.onpointerup=e=>{if(start!==undefined&&Math.abs(e.clientX-start)>60)swipe(document.querySelector('[data-swipe]').dataset.id,e.clientX>start?'like':'skip');start=undefined};card.onkeydown=e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();swipe(document.querySelector('[data-swipe]').dataset.id,e.key==='ArrowRight'?'like':'skip')}}}
}
let swiping=false;
async function swipe(id,action){if(swiping)return;swiping=true;const card=$('.swipe-card');if(card&&!matchMedia('(prefers-reduced-motion: reduce)').matches){card.classList.add(action==='like'?'depart-right':'depart-left');await new Promise(resolve=>setTimeout(resolve,230))}swiping=false;if(me()){if(!await mutate('/api/interactions',{target:id,kind:action}))return}else{state[action==='like'?'liked':'skipped'].push(id);render()}if(action==='like')toast(me()?'Profil gemerkt':'Zum dauerhaften Speichern bitte anmelden.')}
$('[data-close]').onclick=()=>$('#profileDialog').close();
$('#profileForm').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.target);const p={name:String(f.get('name')).trim(),role:f.get('role'),bio:f.get('bio'),tags:f.get('tags'),link:String(f.get('link')||'').trim(),twitch:String(f.get('twitch')||'').trim(),youtube:String(f.get('youtube')||'').trim(),social:String(f.get('social')||'').trim(),collab:f.has('collab')};if(await mutate('/api/profile',p)){$('#profileDialog').close();toast('Profil gespeichert')}};
render();try{state=await api('/api/state');render()}catch{toast('Server nicht erreichbar. Bitte Seite erneut laden.')}
